using System;
using System.Collections;
using System.IO;
using System.Linq;
using Gxdl;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
public static class GuxuAcceptance {
 [MenuItem("GXDL/QA/Guxu Rules")] public static void Rules(){EquipmentTiers.Validate();GuxuUiArt.Validate();GuxuAnimation.ValidateContract();var original=OriginalConfig.Load();GuxuStageRules.SelfTest(original,GuxuStageConfig.Load());GameRules.SelfTest(original);File.WriteAllText("Logs/guxu-rules.txt","PASS: 15 equipment tiers, animation contract, 200 stages, 40 dungeon difficulties, 100 tower floors, original unseal regression. "+DateTime.Now.ToString("O"));}
 [MenuItem("GXDL/QA/Guxu Integration")] public static void Run(){GxdlGame.Instance.StartCoroutine(Check());}
 static Button Find(string name)=>UnityEngine.Object.FindObjectsOfType<Button>().First(b=>b.name==name);
 static IEnumerator Check(){var game=GxdlGame.Instance;string backup=Newtonsoft.Json.JsonConvert.SerializeObject(game.Rules.Save);int tutorialBefore=PlayerPrefs.GetInt(GxdlGame.FirstUnsealStoryKey,-1);PlayerPrefs.SetInt(GxdlGame.FirstUnsealStoryKey,1);try{
 game.Rules.Save.pending=null;game.Rules.Save.peaches=Math.Max(10,game.Rules.Save.peaches);game.Home();int seals=game.Rules.Save.peaches;string equipped=Newtonsoft.Json.JsonConvert.SerializeObject(game.Rules.Save.gear);
 Find("Unseal").onClick.Invoke();Find("Unseal").onClick.Invoke();yield return new WaitForSeconds(.8f);Require(UnityEngine.Object.FindObjectsOfType<GuxuStoneShard>().Any(shard=>shard.MeshBuildCount>0),"fracture mesh actually rendered");ScreenCapture.CaptureScreenshot("Assets/Screenshots/guxu-unseal-fracture.png");yield return new WaitForSeconds(1.8f);
 Require(game.Rules.Save.peaches==seals-1&&game.Rules.Save.pending!=null,"one seal consumption and pending relic");Require(Newtonsoft.Json.JsonConvert.SerializeObject(game.Rules.Save.gear)==equipped,"no implicit equipment replacement");var drop=game.Rules.Save.pending;Require(drop.quality>=1&&drop.quality<=5&&drop.level>=1&&drop.level<=3,"five qualities x three levels");Require(UnityEngine.Object.FindObjectsOfType<Image>().Any(x=>x.name=="Seeker Character Layer")&&UnityEngine.Object.FindObjectsOfType<Image>().Any(x=>x.name=="Sealed Stone Layer"),"independent scene layers");ScreenCapture.CaptureScreenshot("Assets/Screenshots/guxu-home-relic.png");yield return new WaitForEndOfFrame();yield return null;
 int dust=game.Rules.Save.coins,reward=drop.quality*20;Find("Resolve Equipment").onClick.Invoke();game.ResolveDrop(false);yield return new WaitForSeconds(2);Require(game.Rules.Save.coins==dust+reward&&GameRules.ReadSave().coins==dust+reward,"dust balance and persistence");Require(UnityEngine.Object.FindObjectsOfType<Text>().Single(t=>t.name=="Spirit Stone Balance").text=="灵尘 "+(dust+reward),"dust HUD");
 game.Chop();yield return new WaitForSeconds(2.6f);drop=game.Rules.Save.pending;Find("Equip Relic").onClick.Invoke();yield return new WaitForSeconds(2);Require(game.Rules.Save.gear[drop.slot]==drop,"explicit equipment selection");
 game.Rules.Save.keepQuality=1;var test=new Gear{quality=1,level=1,slot=0};Require(game.ShouldKeep(test),"quality retention rule");game.Home();string gearSnapshot=Newtonsoft.Json.JsonConvert.SerializeObject(game.Rules.Save.gear);Find("自动破封").onClick.Invoke();yield return new WaitForSeconds(2.6f);Require(game.Rules.Save.pending!=null&&Newtonsoft.Json.JsonConvert.SerializeObject(game.Rules.Save.gear)==gearSnapshot,"auto pauses without equipping");Find("Resolve Equipment").onClick.Invoke();yield return new WaitForSeconds(2);game.Home();game.StartBattle();yield return new WaitForSeconds(1);ScreenCapture.CaptureScreenshot("Assets/Screenshots/guxu-battle.png");yield return new WaitForEndOfFrame();yield return null;game.Home();int stage=game.Rules.Save.stage;yield return new WaitForSeconds(1);Require(game.Rules.Save.stage==stage,"cancelled battle cannot settle");game.Rules.Save.stage=1;game.Rules.Save.gear[0].attack=100000;game.Home();int sealsBeforeWin=game.Rules.Save.peaches;game.StartBattle();yield return new WaitForSeconds(3);Require(game.Rules.Save.stage==2&&game.Rules.Save.peaches>sealsBeforeWin,"UI battle victory settlement");
 File.WriteAllText("Logs/guxu-integration.txt","PASS: real unseal/resolve/equip buttons, independent art layers, 15-tier drops, no implicit equip, dust+save+HUD, retention, battle cancellation and UI victory settlement. "+DateTime.Now.ToString("O"));
 }finally{if(tutorialBefore<0)PlayerPrefs.DeleteKey(GxdlGame.FirstUnsealStoryKey);else PlayerPrefs.SetInt(GxdlGame.FirstUnsealStoryKey,tutorialBefore);PlayerPrefs.Save();game.Rules.Save=Newtonsoft.Json.JsonConvert.DeserializeObject<SaveData>(backup);game.Rules.Store();game.Home();}}
 static void Require(bool condition,string reason){if(!condition)throw new Exception("Guxu acceptance: "+reason);}
}
